<script setup lang="ts">definePageMeta({layout:'guest',middleware:'guest-access-check'});const route=useRoute();const token=String(route.params.token);useGuestToken().value=token;const{data:providers}=await useFetch<any>('/api/guest/ebike/providers',{query:{token}});const{data:requests,refresh}=await useFetch<any>('/api/guest/ebike/requests',{query:{token}});const form=reactive({partnerId:0,startDate:'',endDate:'',bikeCount:1,guestPhone:'',notes:''});watchEffect(()=>{if(!form.partnerId&&providers.value?.providers?.[0])form.partnerId=providers.value.providers[0].id});const busy=ref(false);const error=ref('');async function submit(){busy.value=true;error.value='';try{await $fetch('/api/guest/ebike/requests',{method:'POST',body:{...form,token}});await refresh()}catch(e:any){error.value=e?.data?.statusMessage||e.message}finally{busy.value=false}}async function pay(id:number){const r=await $fetch<any>(`/api/guest/ebike/${id}/checkout`,{method:'POST',body:{token}});const script=document.createElement('script');script.src='https://gateway.sumup.com/gateway/ecom/card/v2/sdk.js';script.onload=()=>{(window as any).SumUpCard.mount({checkoutId:r.checkoutId,onResponse:()=>{}})};document.head.appendChild(script)}</script>
<template><div class="mx-auto max-w-xl space-y-6 p-5"><div><h1 class="text-2xl font-semibold">🚲 E-bike rental</h1><p class="text-stone-500">Send a request. Payment becomes available after the provider confirms availability.</p></div><div class="space-y-4 rounded-xl bg-white p-5"><select v-model.number="form.partnerId" class="w-full rounded border p-3"><option v-for="p in providers?.providers" :key="p.id" :value="p.id">{{p.name}} · {{p.pricePerDay.toFixed(2)}} EUR/day</option></select><div v-if="providers?.providers?.find((p:any)=>p.id===form.partnerId)?.pickup?.name" class="rounded bg-stone-50 p-3 text-sm"><b>Pickup:</b> {{providers.providers.find((p:any)=>p.id===form.partnerId).pickup.name}} · {{providers.providers.find((p:any)=>p.id===form.partnerId).pickup.address}} <span v-if="providers.providers.find((p:any)=>p.id===form.partnerId).pickup.freeParking">· Free parking</span> <a :href="providers.providers.find((p:any)=>p.id===form.partnerId).pickup.mapsUrl" target="_blank" class="text-pine-700 underline">Google Maps</a></div><div class="grid grid-cols-2 gap-3"><input v-model="form.startDate" type="date" class="rounded border p-3"/><input v-model="form.endDate" type="date" class="rounded border p-3"/></div><input v-model.number="form.bikeCount" type="number" min="1" class="w-full rounded border p-3" placeholder="Number of e-bikes"/><input v-model="form.guestPhone" class="w-full rounded border p-3" placeholder="Phone"/><textarea v-model="form.notes" class="w-full rounded border p-3" placeholder="Notes"/><p v-if="error" class="text-red-600">{{error}}</p><button class="w-full rounded bg-pine-600 p-3 text-white" :disabled="busy" @click="submit">Send request</button></div><div v-for="r in requests?.requests" :key="r.id" class="rounded-xl bg-white p-4"><b>{{r.partnerName}}</b><p>{{r.startDate}}–{{r.endDate}} · {{r.bikeCount}} · {{r.totalPrice.toFixed(2)}} EUR</p><p>Status: {{r.status}}</p><button v-if="r.status==='approved'" class="mt-3 rounded bg-pine-600 px-4 py-2 text-white" @click="pay(r.id)">Pay now</button><div :id="`sumup-card-${r.id}`"/></div></div></template>
